INSERT INTO FLOW_ANALYSIS (
    DEVICE_CODE, TOURISM_NAME, FLOW_COUNT, DIRECTION, CREATE_TIME, UPDATE_TIME
) VALUES (
    #{deviceCode}, #{tourismName}, #{flowCount}, #{direction}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
)

mapper.select:
SELECT

FROM FLOW_ANALYSIS
WHERE DEVICE_CODE = #{deviceCode}
AND CREATE_TIME BETWEEN #{startTime} AND #{endTime}
ORDER BY CREATE_TIME DESC

SELECT

FROM FLOW_ANALYSIS
WHERE TOURISM_NAME = #{tourismName}
AND CREATE_TIME BETWEEN #{startTime} AND #{endTime}
ORDER BY CREATE_TIME DESC

SELECT EXTRACT(HOUR FROM CREATE_TIME) as HOUR, COUNT(1) as COUNT, SUM(FLOW_COUNT) as TOTAL_FLOW FROM FLOW_ANALYSIS WHERE 1=1
AND DEVICE_CODE = #{deviceCode}
AND TOURISM_NAME = #{tourismName}
AND CREATE_TIME BETWEEN #{startTime} AND #{endTime} GROUP BY EXTRACT(HOUR FROM CREATE_TIME) ORDER BY HOUR

SELECT 
    DIRECTION,
    COUNT(1) as COUNT,
    SUM(FLOW_COUNT) as TOTAL_FLOW
FROM FLOW_ANALYSIS
WHERE 1=1

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}

AND CREATE_TIME BETWEEN #{startTime} AND #{endTime}
GROUP BY DIRECTION

SELECT 
    DATE_TRUNC('hour', CREATE_TIME) as TIME_POINT,
    SUM(FLOW_COUNT) as TOTAL_FLOW
FROM FLOW_ANALYSIS
WHERE 1=1

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}

AND CREATE_TIME BETWEEN #{startTime} AND #{endTime}
GROUP BY DATE_TRUNC('hour', CREATE_TIME)
ORDER BY TIME_POINT

SELECT

FROM FLOW_ANALYSIS
WHERE TOURISM_NAME = #{tourismName}
AND CREATE_TIME BETWEEN #{startTime} AND #{endTime}
ORDER BY CREATE_TIME DESC
